import click
import black
from pathlib import Path
from tempfile import TemporaryDirectory
from unittest import TestCase

class TestBlackConfig(TestCase):
    def test_read_pyproject_toml_rejects_non_string_regex_configs(self):
        # We need a FakeContext because read_pyproject_toml expects one
        class FakeContext:
            def __init__(self):
                self.params = {}
                self.default_map = {}
                self.command = MagicMock()

        from unittest.mock import MagicMock
        fake_ctx = FakeContext()

        with TemporaryDirectory() as workspace:
            root = Path(workspace)
            pyproject_toml = root / "pyproject.toml"

            for key, option in [("include", "include"), ("force-exclude", "force-exclude")]:
                pyproject_toml.write_text(f' [tool.black]\n {key} = ["not-a-string"]\n')
                with self.assertRaises(click.BadOptionUsage) as cm:
                    black.read_pyproject_toml(fake_ctx, None, str(pyproject_toml))
                self.assertEqual(cm.exception.option, option)

if __name__ == "__main__":
    import unittest
    unittest.main()
